{"path": "task.py", "content": "import heapq

def heap_merge(*args):
    heap = []
    iterators = []
    for arg in args:
        it = iter(arg)
        try:
            val = next(it)
            heap.append((val, it))
            iterators.append(it)
        except StopIteration:
            continue
    heapq.heapify(heap)
    result = []
    while heap:
        val, it = heapq.heappop(heap)
        result.append(val)
        try:
            next_val = next(it)
            heapq.heappush(heap, (next_val, it))
        except StopIteration:
            pass
    return result"}

